/// Registers the bundled Manrope faces (data assets "manrope-regular", "manrope-medium", "manrope-semibold", "manrope-bold") with Core Text. Call once at launch in the
/// app and in each extension that renders text; a target without the assets keeps the system font.
enum AgaraFontRegistry {
    private static var registered = false
    static func registerBundledFonts() {
        guard !registered else { return }
        registered = true
        for asset in ["manrope-regular", "manrope-medium", "manrope-semibold", "manrope-bold"] {
            guard let data = NSDataAsset(name: asset)?.data,
                  let provider = CGDataProvider(data: data as CFData),
                  let font = CGFont(provider) else { continue }
            CTFontManagerRegisterGraphicsFont(font, nil)
        }
    }
}

